render_chart <- function(data, cfg, manifest) { chart_validate_columns(data, list(x = cfg$x, y = cfg$y), c("x", "y")); n <- nrow(data); cols <- ceiling(sqrt(n)); cells <- data.frame(region = as.character(data[[cfg$x]]), value = data[[cfg$y]], col = (seq_len(n) - 1) %% cols, row = (seq_len(n) - 1) %/% cols); p <- ggplot2::ggplot(cells, ggplot2::aes(x = col, y = row, fill = value)) + ggplot2::geom_tile(colour = "white", linewidth = 0.8) + ggplot2::geom_text(ggplot2::aes(label = region), size = 3) + ggplot2::scale_fill_gradient(low = "#E2E8F0", high = cfg$color %||% "#0A84FF") + ggplot2::coord_equal() + ggplot2::theme_void() + ggplot2::labs(title = cfg$title %||% "方格统计地图", fill = "数值"); chart_open_device(cfg$outputPath, cfg$format); print(p); grDevices::dev.off(); cfg$outputPath }
